import{_ as i}from"./plugin-vue_export-helper-c27b6911.js";import{r as d,o as l,c as r,d as n,e,b as a,w as t,a as o,f as c}from"./app-9334da21.js";const p={},u=n("p",null,"这一篇按「解决什么问题 → 原理 → 参数怎么定 → 代价与坑」梳理设备端最常用的算法：滤波、动态处理、采样率转换、波束成形、AEC、NS、VAD。",-1),g=n("p",null,"重点不是背公式，而是为什么在端侧选它、什么时候不该选它，以及它会给延迟和 CPU 带来什么。",-1),v=c(`<h2 id="_2-常用音频处理算法" tabindex="-1"><a class="header-anchor" href="#_2-常用音频处理算法" aria-hidden="true">#</a> 2. 常用音频处理算法</h2><p>算法章节的组织方式：<strong>解决什么问题 → 原理与公式 → 参数怎么定 → 代价与坑</strong>。面试时能说清「为什么不用另一个」比背公式更加分。</p><h3 id="_2-1-增益、混音、削波与限幅" tabindex="-1"><a class="header-anchor" href="#_2-1-增益、混音、削波与限幅" aria-hidden="true">#</a> 2.1 增益、混音、削波与限幅</h3><p><strong>增益换算</strong>（必须条件反射）：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>线性增益 g = 10^(dB/20)
-6 dB ≈ 0.5，-3 dB ≈ 0.707，+6 dB ≈ 2.0
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>混音</strong>：多路直接相加会溢出。两种做法：</p><ul><li>固定衰减：N 路各乘 <code>1/N</code>（或 <code>1/sqrt(N)</code>），简单但保守。</li><li>统计/自适应：按实际峰值或响度归一化，音质更好但需要 lookahead。</li></ul><p><strong>削波</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>hard clip: y = clamp(x, -1, 1)        → 产生大量高次谐波，听感“破”
soft clip: y = tanh(kx)/tanh(k)       → 平滑饱和，适合保护
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>限幅器（limiter）</strong>：当信号超过阈值时快速压到阈值，关键是 <strong>lookahead</strong>——提前看到峰值，用 ramp 把增益降下来，避免瞬态失真。</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>延迟 = lookahead 长度（常见 1—5 ms）
增益包络：attack &lt; 1 ms，release 50—200 ms
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>真峰值</strong>：采样点之间可能过载，用 4× 过采样检测（ITU-R BS.1770 / EBU R128），流媒体发布链路必备。</p><p><strong>淡入淡出</strong>：10—20 ms 线性或余弦 ramp，避免阶跃。设备启停、切歌、静音都走 ramp，否则就是 pop。</p><h3 id="_2-2-滤波器与双二阶-biquad" tabindex="-1"><a class="header-anchor" href="#_2-2-滤波器与双二阶-biquad" aria-hidden="true">#</a> 2.2 滤波器与双二阶（Biquad）</h3><p><strong>FIR vs IIR</strong>：</p><table><thead><tr><th>维度</th><th>FIR</th><th>IIR</th></tr></thead><tbody><tr><td>相位</td><td>可严格线性（对称系数）</td><td>非线性，频率相关群延迟</td></tr><tr><td>阶数</td><td>高（几百 tap）</td><td>低（几个 biquad）</td></tr><tr><td>稳定性</td><td>恒稳定</td><td>需检查极点</td></tr><tr><td>计算量</td><td>大</td><td>小</td></tr><tr><td>典型用途</td><td>线性相位 EQ、SRC、波束成形</td><td>实时 EQ、分频、去直流、AEC 预加重</td></tr></tbody></table><p>线性相位 FIR 的群延迟：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>N 阶（N+1 抽头）对称 FIR：群延迟 = N/2 个采样
48 kHz 下 1024 tap → 10.7 ms
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>这就是「线性相位好听但延迟高」的来源。</p><p><strong>双二阶（biquad）</strong> 是设备端最常用的 IIR 结构。差分方程：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>y[n] = b0*x[n] + b1*x[n-1] + b2*x[n-2] - a1*y[n-1] - a2*y[n-2]
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>DF2T（转置直接 II 型）</strong> 数值特性最好，每样本只需 2 个状态：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">typedef</span> <span class="token keyword">struct</span> <span class="token punctuation">{</span>
    <span class="token keyword">float</span> b0<span class="token punctuation">,</span> b1<span class="token punctuation">,</span> b2<span class="token punctuation">,</span> a1<span class="token punctuation">,</span> a2<span class="token punctuation">;</span>   <span class="token comment">/* a0 已归一化为 1 */</span>
    <span class="token keyword">float</span> z1<span class="token punctuation">,</span> z2<span class="token punctuation">;</span>
<span class="token punctuation">}</span> <span class="token class-name">biquad_t</span><span class="token punctuation">;</span>

<span class="token keyword">static</span> <span class="token keyword">inline</span> <span class="token keyword">float</span> <span class="token function">biquad_df2t</span><span class="token punctuation">(</span><span class="token class-name">biquad_t</span> <span class="token operator">*</span>q<span class="token punctuation">,</span> <span class="token keyword">float</span> x<span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">float</span> y  <span class="token operator">=</span> q<span class="token operator">-&gt;</span>b0 <span class="token operator">*</span> x <span class="token operator">+</span> q<span class="token operator">-&gt;</span>z1<span class="token punctuation">;</span>
    q<span class="token operator">-&gt;</span>z1    <span class="token operator">=</span> q<span class="token operator">-&gt;</span>b1 <span class="token operator">*</span> x <span class="token operator">-</span> q<span class="token operator">-&gt;</span>a1 <span class="token operator">*</span> y <span class="token operator">+</span> q<span class="token operator">-&gt;</span>z2<span class="token punctuation">;</span>
    q<span class="token operator">-&gt;</span>z2    <span class="token operator">=</span> q<span class="token operator">-&gt;</span>b2 <span class="token operator">*</span> x <span class="token operator">-</span> q<span class="token operator">-&gt;</span>a2 <span class="token operator">*</span> y<span class="token punctuation">;</span>
    <span class="token keyword">return</span> y<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>RBJ Audio EQ Cookbook</strong> 系数（<code>w0 = 2*pi*f0/fs</code>，<code>alpha = sin(w0)/(2Q)</code>）：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>低通 LPF:
  b0 = (1 - cos w0)/2      b1 = 1 - cos w0      b2 = (1 - cos w0)/2
  a0 = 1 + alpha           a1 = -2 cos w0       a2 = 1 - alpha

高通 HPF:
  b0 = (1 + cos w0)/2      b1 = -(1 + cos w0)   b2 = (1 + cos w0)/2
  a0 = 1 + alpha           a1 = -2 cos w0       a2 = 1 - alpha

峰值 EQ（增益 G dB，A = 10^(G/40)）:
  b0 = 1 + alpha*A         b1 = -2 cos w0       b2 = 1 - alpha*A
  a0 = 1 + alpha/A         a1 = -2 cos w0       a2 = 1 - alpha/A

陷波 Notch:
  b0 = 1                   b1 = -2 cos w0       b2 = 1
  a0 = 1 + alpha           a1 = -2 cos w0       a2 = 1 - alpha
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Q 与带宽的换算（<code>BW</code> 为八度）：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>1/Q = 2 * sinh( ln(2)/2 * BW * w0/sin(w0) )
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>低频数值精度</strong>：<code>f0 &lt;&lt; fs</code> 时 <code>cos(w0) → 1</code>，极点紧贴单位圆，float 系数误差会被放大。对策：</p><ul><li>用 <code>double</code> 计算系数，或运行时用 double 状态；</li><li>用 DF2T 而非 DF1；</li><li>极低频用一阶高通/去直流替代；</li><li>必要时用状态空间/耦合形式（coupled form）。</li></ul><p><strong>去直流与语音高通</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>一阶 DC blocker: y[n] = x[n] - x[n-1] + R*y[n-1]，R ≈ 0.995—0.999
语音高通：80—120 Hz，二阶 Butterworth（Q ≈ 0.707）
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>语音链路先去直流/低频（风机噪声、电源 hum、手持振动），再做其他处理；否则 AEC/NS 的估计会被低频污染。</p><p><strong>滤波器设计方法</strong>：</p><ul><li>窗函数法（Hann/Hamming/Blackman/Kaiser）：简单，主瓣/旁瓣折中，Kaiser 可调 β。</li><li>Parks-McClellan（等波纹）：给定通带/阻带指标求最优 FIR。</li><li>模拟原型 + 双线性变换：Butterworth/Chebyshev/Elliptic → biquad。</li><li>工程上直接用 <code>scipy.signal.butter/cheby2/firwin/remez</code> 设计，导出 SOS，避免高阶直接型数值问题。</li></ul><p><strong>常见指标</strong>：通带纹波 &lt; 0.1 dB、阻带衰减 &gt; 60—100 dB、过渡带宽度、群延迟。</p><h3 id="_2-3-动态处理-压缩、限幅、agc" tabindex="-1"><a class="header-anchor" href="#_2-3-动态处理-压缩、限幅、agc" aria-hidden="true">#</a> 2.3 动态处理：压缩、限幅、AGC</h3><p><strong>压缩器</strong>四参数：</p><ul><li><strong>Threshold（T）</strong>：超过才压缩。</li><li><strong>Ratio（R）</strong>：输入增加 R dB，输出只增加 1 dB。</li><li><strong>Attack / Release</strong>：增益变化的快慢。</li><li><strong>Knee</strong>：硬拐点/软拐点。</li></ul><p>增益计算（dB 域）：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>x_dB = 20*log10(|x|)
y_dB = x_dB                                    if x_dB &lt;= T
y_dB = T + (x_dB - T)/R                        if x_dB &gt; T
gain_dB = y_dB - x_dB
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>平滑（一阶）：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>alpha_att = exp(-1/(fs * tau_att))
alpha_rel = exp(-1/(fs * tau_rel))
g = alpha*g_prev + (1-alpha)*g_target
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>实现要点：</p><ul><li>检测器用 <strong>peak</strong>（快速、保守）或 <strong>RMS</strong>（平滑、贴合听感）。</li><li>attack 太短会产生失真（尤其低频），太长会漏掉瞬态；release 太短会“抽吸”（pumping）。</li><li>立体声必须<strong>联动</strong>（link），否则声像会漂移。</li><li>压缩后加 makeup gain，注意别把峰值推过 0 dBFS。</li></ul><p><strong>AGC（自动增益控制）</strong> 与压缩器的区别：AGC 的目标是<strong>把长期电平稳定到目标值</strong>，时间常数更长（几百 ms 到几秒），通常带噪声门/静音检测，避免安静时把噪声拉满。</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>目标电平：语音常用 -26 ~ -18 dBFS（ASR 前），通话 -20 dBFS 左右
攻击 100—500 ms，释放 1—5 s
噪声门阈值：高于底噪 6—10 dB 才启用
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>多段 DRC</strong>：把频带分成 2—3 段分别压缩，避免低频能量触发全带压缩（手机扬声器保护常用）。</p><h3 id="_2-4-采样率转换-src-asrc" tabindex="-1"><a class="header-anchor" href="#_2-4-采样率转换-src-asrc" aria-hidden="true">#</a> 2.4 采样率转换（SRC / ASRC）</h3><p><strong>为什么需要</strong>：44.1 kHz 内容 → 48 kHz 设备；16 kHz 语音 → 48 kHz 通话链路；两个时钟域之间吸收 ppm 漂移。</p><p><strong>有理数重采样 L/M</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>先插值 L 倍（补零 + 低通），再抽取 M 倍（低通 + 取点）
目标：44.1k → 48k = 160/147
滤波器截止：min(fs_in, fs_out)/2
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>多相（polyphase）实现</strong>：把滤波器系数按相位分组，每个输出点只算一个相位，复杂度从 O(L) 降到 O(1) 组。</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>p = (m*M) mod L                                  （相位）
y[m] = Σ_q h[p + q*L] * x[ floor(m*M/L) - q ]     （只取该相位的系数）
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>sinc 插值</strong>（任意比率）：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>y(t) = Σ_n x[n] * sinc((t - nT)/T) * w(t - nT)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>窗函数截断 sinc，抽头数决定质量；典型 32—128 抽头。</p><p><strong>ASRC</strong>：输入输出时钟独立，用<strong>分数延迟</strong>（Farrow 结构、立方插值）连续调整读取位置。Farrow 立方：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>y(μ) = c0 + c1*μ + c2*μ² + c3*μ³，μ ∈ [0,1)
系数由相邻 4 个样本线性组合得到
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>质量指标</strong>：</p><ul><li>通带纹波（&lt; 0.01—0.1 dB）</li><li>阻带衰减（&gt; 90—120 dB）</li><li>THD+N、混叠/镜像抑制</li><li>群延迟与 CPU</li></ul><p><strong>常用库</strong>：libsamplerate（sinc 最佳质量）、soxr、Speex resampler（定点友好）、ALSA <code>speexrate</code> 插件、zita-resampler。</p><p><strong>坑</strong>：</p><ul><li>劣质线性插值会在高频产生明显混叠，语音听感“发闷/发毛”。</li><li>重采样会改变延迟，AEC 的参考对齐要重新算。</li><li>44.1↔48 反复转换会累积损伤，链路中尽量只转一次。</li></ul><h3 id="_2-5-麦克风阵列与波束成形" tabindex="-1"><a class="header-anchor" href="#_2-5-麦克风阵列与波束成形" aria-hidden="true">#</a> 2.5 麦克风阵列与波束成形</h3><p><strong>远场模型</strong>：平面波到达不同麦克风的时延差。</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>τ_m = (m * d * sinθ) / c
d：阵元间距，θ：入射角，c ≈ 343 m/s
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>延迟求和（delay-and-sum）</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>y(t) = (1/M) * Σ_m x_m(t - τ_m)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><ul><li>对目标方向相干增强，对其他方向部分抵消。</li><li>主瓣宽度 ∝ λ/(M d)，阵元越多/间距越大越窄。</li><li><strong>空间混叠</strong>：<code>d &gt; λ/2</code> 会出现栅瓣；16 kHz 的 λ/2 ≈ 10.7 mm，所以阵列间距通常 10—40 mm，需要权衡低频性能。</li></ul><p><strong>分数延迟</strong>：<code>τ_m</code> 不是整数采样，需 sinc 插值或 Farrow 滤波器，否则高频指向性会偏。</p><p><strong>MVDR（最小方差无失真响应）</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>w = R^-1 * d / (d^H * R^-1 * d)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><ul><li><code>R</code> 是噪声+干扰协方差，<code>d</code> 是目标方向导向矢量。</li><li>理论最优，但对 <code>R</code> 估计误差敏感，需要<strong>对角加载</strong>（<code>R + εI</code>）和协方差估计的平滑。</li><li>计算量：M×M 矩阵求逆，M=4 时可接受；M=8 以上要考虑降维或子带处理。</li></ul><p><strong>GSC（广义旁瓣抵消）</strong>：固定波束成形 + 阻塞矩阵 + 自适应噪声抵消，把约束优化转成无约束自适应，工程上更常用。</p><p><strong>近场 vs 远场</strong>：小房间/近讲（&lt; 0.5 m）要用球面波模型，时延差之外还有幅度差。</p><p><strong>DOA（波达方向）</strong>：</p><ul><li>GCC-PHAT：对互谱做相位加权，抑制混响，峰值即 TDOA。</li></ul><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>R12(τ) = IFFT( X1(f) * conj(X2(f)) / |X1(f) * conj(X2(f))| )
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><ul><li>SRP-PHAT：对所有方向做相位变换求和，鲁棒但计算量大。</li><li>MUSIC：子空间分解，高分辨率，需要多快拍和阵元数。</li></ul><p><strong>工程约束</strong>：</p><ul><li>阵列几何（线性/环形/三角）决定 360° 覆盖与盲区。</li><li>麦克风一致性（灵敏度/相位）差会导致零陷变浅，产线要校准。</li><li>波束成形会放大自噪声，<strong>低频白噪声增益</strong>要检查。</li><li>输出通常还要接 AEC/NS，顺序见 2.9。</li></ul><h3 id="_2-6-回声消除-aec" tabindex="-1"><a class="header-anchor" href="#_2-6-回声消除-aec" aria-hidden="true">#</a> 2.6 回声消除（AEC）</h3><p><strong>问题模型</strong>（扬声器→麦克风的声学回声）：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>d(n) = s(n) + Σ_k h_k * x(n-k) + v(n)
d：麦克风信号，s：近端语音，x：远端参考，h：回声路径，v：噪声
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>目标是估计 <code>h</code>，重建回声 <code>ŷ</code>，从 <code>d</code> 中减掉，保留 <code>s</code>。</p><p><strong>NLMS（归一化最小均方）</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>ŷ(n) = w^T(n) * x(n)
e(n) = d(n) - ŷ(n)
w(n+1) = w(n) + μ * e(n) * x(n) / (||x(n)||² + δ)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>μ</code> 典型 0.1—0.5；太大会发散，太小收敛慢。</li><li>滤波器长度要覆盖房间混响尾部：<strong>200—500 ms</strong>；16 kHz 下 3200—8000 tap。时域直接卷积 CPU 太高。</li></ul><p><strong>PBFDAF（分块频域自适应滤波）</strong>：把长滤波器分成 B 块，每块 2N 点 FFT，overlap-save 卷积 + 频域 NLMS + 时域约束。每块的计算量约 O(B·N + N log N)，摊到每样本约 O(B + log N)，远低于时域 O(L)，是设备端主流。</p><p><strong>双讲检测（DTD）</strong>：近端说话时自适应必须冻结，否则会“学掉”近端语音。</p><ul><li>Geigel 算法：<code>|d| &gt; max|x| * threshold</code>。</li><li>归一化互相关/相干性。</li><li>双滤波器（foreground/background）比较。</li></ul><p><strong>非线性残留（NLP/RES）</strong>：扬声器、功放、ADC 的非线性使线性 AEC 消不干净，需要残余回声抑制——用估计的回声能量做谱增益，类似 NS。</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>ERLE = 10*log10( E[d²] / E[e²] )   （单讲时）
典型线性 AEC：20—40 dB；加 NLP 后 45—60 dB
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>工程要点</strong>：</p><ul><li><strong>参考信号对齐</strong>：参考路径有 buffer/算法延迟，必须先估计并补偿（互相关/GCC-PHAT），否则滤波器长度爆炸。</li><li><strong>时钟漂移</strong>：参考与麦克风不同源时，延迟缓慢变化，需要跟踪（AEC3 的做法）。</li><li><strong>设备形态</strong>：手机/会议 bar/智能音箱的扬声器-麦克风耦合差异极大，滤波器长度和 NLP 强度要按机型调。</li><li><strong>CPU</strong>：16 kHz、200 ms 尾长、PBFDAF 在 A53 上约 5—15% 单核；48 kHz 全带宽 AEC 翻倍以上。</li></ul><p><strong>AEC / ANC / NS 的区别</strong>（容易混）：</p><ul><li><strong>AEC</strong>：消除「自己播放、又被自己麦克风收回来」的回声，必须有参考信号。</li><li><strong>ANC</strong>：耳机/音箱用反相声波抵消环境噪声，分前馈/反馈/混合，不需要参考信号。</li><li><strong>NS</strong>：抑制环境噪声，不针对特定参考；单通道或多通道均可。</li><li>补充指标：<code>ERL</code> 是回声路径本身的衰减，<code>ERLE</code> 是 AEC 在 ERL 基础上额外抑制的量。</li></ul><h3 id="_2-7-噪声抑制-ns" tabindex="-1"><a class="header-anchor" href="#_2-7-噪声抑制-ns" aria-hidden="true">#</a> 2.7 噪声抑制（NS）</h3><p><strong>STFT 域处理</strong>：分帧（20—32 ms）→ 加窗（sqrt-Hann）→ FFT → 估计噪声 → 计算增益 → IFFT → overlap-add。</p><p><strong>谱减法</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>|Ŝ(f)|² = max( |Y(f)|² - α*|N̂(f)|² , β*|Y(f)|² )
α：过减因子（1—4），β：谱下限（0.01—0.1）
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>维纳滤波</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>G = ξ / (1 + ξ)
ξ：先验 SNR，γ：后验 SNR
判决引导估计：ξ = α*|Ŝ_prev|²/λ_n + (1-α)*max(γ-1, 0)，α ≈ 0.98
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>MMSE-LSA</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>G = ξ/(1+ξ) * exp( 0.5 * ∫_v^∞ e^-t / t dt )
v = ξ*γ/(1+ξ)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>噪声估计</strong>：MCRA（最小值控制递归平均）、最小统计量、VAD 辅助。噪声估计不准是 NS 失败的头号原因。</p><p><strong>musical noise（音乐噪声）</strong>：谱减过度导致随机残留音。缓解：</p><ul><li>过减 + 谱下限；</li><li>增益在时间/频率上平滑；</li><li>维纳/MMSE 类软判决；</li><li>深度学习方法直接回归掩码。</li></ul><p><strong>深度学习 NS</strong>：RNNoise（GRU，48 kHz 实时）、DCCRN/CRN、DeepFilterNet。设备端关注：参数量、MACs、定点/量化、内存带宽、是否支持流式。</p><p><strong>评价指标</strong>：</p><ul><li>客观：PESQ（窄带/宽带）、STOI（可懂度）、DNSMOS、SNR 提升。</li><li>任务级：ASR 词错率（WER）、唤醒率/误唤醒。</li><li>注意：PESQ 高不等于 ASR 好，语音增强可能损伤识别线索。</li></ul><h3 id="_2-8-vad、去混响、丢包补偿" tabindex="-1"><a class="header-anchor" href="#_2-8-vad、去混响、丢包补偿" aria-hidden="true">#</a> 2.8 VAD、去混响、丢包补偿</h3><p><strong>VAD</strong>：</p><ul><li>能量 + 过零率 + 谱特征，最简单。</li><li>GMM（WebRTC VAD，mode 0—3，mode 3 最激进）。</li><li>DNN VAD（更鲁棒，代价是算力）。</li><li><strong>hangover</strong>：语音结束后保持 100—300 ms，避免尾音被切。</li></ul><p><strong>去混响 WPE（Weighted Prediction Error）</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>x(t,f) = Σ_{τ=1..D} G(τ,f) * x(t-τ,f) + d(t,f)
估计线性预测系数 G，从当前帧减掉晚期混响
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>多通道 WPE 效果最好，计算量在 STFT 域，适合会议/车载。</p><p><strong>丢包补偿（PLC）</strong>：</p><ul><li>波形相似重复（WSOLA）、基音周期复制。</li><li>Opus 内置 PLC，LC3 也有。</li><li>网络抖动用 jitter buffer（20—200 ms）吸收，代价是延迟。</li></ul><h3 id="_2-9-语音前端链路顺序与工程约束" tabindex="-1"><a class="header-anchor" href="#_2-9-语音前端链路顺序与工程约束" aria-hidden="true">#</a> 2.9 语音前端链路顺序与工程约束</h3><p>典型顺序（多麦远场）：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>ADC → DC/HPF → 波束成形 → AEC → NS → AGC → VAD → 编码/ASR
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>为什么这么排：</p><ul><li><strong>HPF 最前</strong>：去掉 DC、低频振动、电源 hum，避免污染后续估计。</li><li><strong>BF 在 AEC 前</strong>：先提升目标方向 SNR；AEC 的参考是远端信号，与 BF 无关。也有把 AEC 放 BF 前的方案（每麦独立 AEC），代价是算力 ×M。</li><li><strong>AEC 在 NS 前</strong>：NS 是非线性/时变处理，会破坏回声路径的线性，导致 AEC 失效。</li><li><strong>AGC 在 NS 后</strong>：否则会把噪声一起放大；AGC 也会影响 VAD，所以 VAD 常取 AGC 前或做增益补偿。</li><li><strong>VAD 最后</strong>：给编码器/唤醒词做门控。</li></ul><p>其他约束：</p><ul><li><strong>帧长对齐</strong>：10 ms @16 kHz = 160 点；AEC 常用 64/128 块；STFT 用 256/512 点。链路中要有统一的帧调度器，避免反复重采样。</li><li><strong>采样率统一</strong>：麦克风 48 kHz 采集 → 降采样到 16 kHz 做语音；AEC 若在 48 kHz 做，参考也必须 48 kHz。</li><li><strong>别做两次 AGC/NS</strong>：串接会累积损伤，调参也失控。</li><li><strong>旁路（bypass）能力</strong>：调试和对比必须能逐级旁路，否则无法定位是哪一级变差。</li></ul><h3 id="_2-10-语音编解码与传输-简述" tabindex="-1"><a class="header-anchor" href="#_2-10-语音编解码与传输-简述" aria-hidden="true">#</a> 2.10 语音编解码与传输（简述）</h3><table><thead><tr><th>编码</th><th>帧长</th><th>码率</th><th>特点</th></tr></thead><tbody><tr><td>Opus</td><td>2.5—60 ms</td><td>6—510 kbps</td><td>语音/音乐通用，内置 PLC/FEC，WebRTC 默认</td></tr><tr><td>AAC-LC</td><td>1024 点</td><td>64—256 kbps</td><td>音乐主流</td></tr><tr><td>LC3</td><td>7.5/10 ms</td><td>16—320 kbps</td><td>BLE Audio 强制，低延迟低功耗</td></tr><tr><td>SBC</td><td>—</td><td>200—345 kbps</td><td>经典蓝牙 A2DP，质量一般</td></tr><tr><td>G.711</td><td>20 ms</td><td>64 kbps</td><td>传统电话，PLC 简单</td></tr></tbody></table><p>传输侧关注：<strong>jitter buffer</strong>（抗抖动 vs 延迟）、<strong>FEC/PLC</strong>（丢包）、<strong>拥塞控制</strong>（WebRTC GCC）。蓝牙链路的延迟主要来自编解码 + 重传 + 缓冲，A2DP 100—200 ms，LE Audio 20—50 ms。</p><hr>`,130),m=n("strong",null,"系列导航",-1),b=n("strong",null,"下一篇",-1);function h(x,k){const s=d("RouterLink");return l(),r("div",null,[n("blockquote",null,[n("p",null,[e("本文是「设备端音频与语音处理」系列第 2 篇（共 7 篇）。系列导览："),a(s,{to:"/source-study/audio/"},{default:t(()=>[e("从 pipeline 到 Linux 音频栈")]),_:1}),e("。")])]),u,g,o(" more "),v,n("p",null,[m,e("："),a(s,{to:"/source-study/audio/"},{default:t(()=>[e("系列导览")]),_:1}),e(" · "),b,e("："),a(s,{to:"/source-study/audio/03-linux-audio-stack.html"},{default:t(()=>[e("设备端音频（三）：Linux 音频栈")]),_:1})])])}const A=i(p,[["render",h],["__file","02-audio-algorithms.html.vue"]]);export{A as default};
